package io.atlas.modules.market.menu;
import net.minecraft.world.item.*;import net.minecraft.world.item.component.ItemLore;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import com.cobblemon.mod.common.pokemon.Pokemon;import java.util.*;import io.atlas.modules.market.model.MarketPolicy;
final class MarketVisual {
 static ItemStack icon(ItemStack stack,String name,List<String> lines){stack=stack.copy();stack.set(DataComponents.CUSTOM_NAME,Component.literal(name));stack.set(DataComponents.LORE,new ItemLore(lines.stream().map(Component::literal).map(c->(Component)c).toList()));return stack;}
 static ItemStack icon(Item item,String name,String... lines){return icon(new ItemStack(item),name,Arrays.asList(lines));}
 static ItemStack pokemon(Pokemon pokemon){return io.atlas.modules.market.service.MarketSpriteIcons.from(pokemon);}
 static ItemStack pokemonChoice(Pokemon pokemon,int slot){var lore=stats(pokemon);lore.add("§7Espaço "+slot+" da equipe");lore.add("§eClique para anunciar.");return icon(pokemon(pokemon),"§b"+pokemon.getSpecies().getName()+" §e• Nível "+pokemon.getLevel(),lore);}
 static List<String> stats(Pokemon p){var out=new ArrayList<String>();out.add("§7Habilidade: §e"+p.getAbility().getName()+(new com.cobblemon.mod.common.pokemon.properties.HiddenAbilityProperty(true).matches(p)?" §d(HA)":""));out.add("§7Natureza: §e"+p.getNature().getName().getPath());out.add("§7Gênero: §e"+switch(p.getGender()){case MALE->"Macho ♂";case FEMALE->"Fêmea ♀";default->"Nenhum";});out.add("§7Tamanho: §e"+String.format(Locale.forLanguageTag("pt-BR"),"%.2f×",p.getScaleModifier()));out.add("§7Textura: §e"+(p.getShiny()?"Shiny ★":"Original"));out.add("§7Forma: §e"+p.getForm().getName());
  var stats=new com.cobblemon.mod.common.api.pokemon.stats.Stats[]{com.cobblemon.mod.common.api.pokemon.stats.Stats.HP,com.cobblemon.mod.common.api.pokemon.stats.Stats.ATTACK,com.cobblemon.mod.common.api.pokemon.stats.Stats.DEFENCE,com.cobblemon.mod.common.api.pokemon.stats.Stats.SPECIAL_ATTACK,com.cobblemon.mod.common.api.pokemon.stats.Stats.SPECIAL_DEFENCE,com.cobblemon.mod.common.api.pokemon.stats.Stats.SPEED};int[] ivs=Arrays.stream(stats).mapToInt(s->p.getIvs().get(s)).toArray(),evs=Arrays.stream(stats).mapToInt(s->p.getEvs().get(s)).toArray();int iv=Arrays.stream(ivs).sum(),ev=Arrays.stream(evs).sum();out.add("§8────────────────────");out.add("§7IVs: §e"+iv+"/186 §a("+percentage(iv,186)+")");out.add(statsLine(ivs,0));out.add(statsLine(ivs,3));out.add(" ");out.add("§7EVs: §e"+ev+"/510 §a("+percentage(ev,510)+")");out.add(statsLine(evs,0));out.add(statsLine(evs,3));var moves=new ArrayList<String>();for(var move:p.getMoveSet())if(move!=null)moves.add(move.getDisplayName().getString());out.add(" ");out.add("§7Golpes: §f"+String.join(", ",moves));out.add("§7Item segurado: §f"+p.heldItem().getHoverName().getString());return out;
 }
 private static String percentage(int value,int max){return String.format(Locale.forLanguageTag("pt-BR"),"%.2f%%",value*100.0/max);}
 private static String statsLine(int[] v,int start){String[] labels={"§cHP","§6Atk","§eDef","§9SpA","§aSpD","§dSpe"};return labels[start]+": §f"+v[start]+" §7/ "+labels[start+1]+": §f"+v[start+1]+" §7/ "+labels[start+2]+": §f"+v[start+2];}
 static ItemStack preview(ServerPlayer player,String kind,String payload,String name,long price,String owner,String server,java.time.Instant expires){try{var lines=new ArrayList<String>();ItemStack icon;if(kind.equals("ITEM")){icon=ItemStack.CODEC.parse(player.getServer().registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE),com.google.gson.JsonParser.parseString(payload)).getOrThrow();lines.add("§7Tipo: §f"+net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(icon.getItem()));lines.add("§7Quantidade: §e"+icon.getCount());for(var line:icon.getOrDefault(DataComponents.LORE,new ItemLore(List.of())).lines())lines.add(line.getString());}else{var p=new Pokemon().loadFromJSON(player.getServer().registryAccess(),com.google.gson.JsonParser.parseString(payload).getAsJsonObject());icon=pokemon(p);lines.addAll(stats(p));}lines.add("§8────────────────────");lines.add("§7Preço total: §b"+MarketPolicy.formatPrice(price));lines.add("§7Moeda: §eCobbleDollars");lines.add("§7Vendedor: §e"+owner);lines.add("§7Servidor: §a"+server);if(expires!=null)lines.add("§7Expira em: §a"+MarketPolicy.remaining(expires));lines.add(" ");lines.add("§7Sem taxa aplicada");return icon(icon,(kind.equals("POKEMON")?"§b":"§f")+name,lines);}catch(Exception e){return icon(Items.BARRIER,"§cPrévia indisponível","§7Atualize o GTS.");}}
}
